mapper.select:
SELECT

FROM sys_audit_log

    is_deleted = 0

        AND biz_code LIKE CONCAT('%', #{param.bizCode}, '%')


        AND module = #{param.module}


        AND biz_type = #{param.bizType}


        AND operate_type = #{param.operateType}


        AND operate_by LIKE CONCAT('%', #{param.operateBy}, '%')


        AND result_status = #{param.resultStatus}


        AND operate_time >= #{param.timeStart}


        AND operate_time < #{param.timeEnd}


ORDER BY operate_time DESC, id DESC
